import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import axios from 'axios';
import { authApi } from '@/api/auth.api';
import styles from './auth.module.css';

const schema = z
  .object({
    otp: z
      .string()
      .length(6, 'Enter the 6-digit code')
      .regex(/^\d+$/, 'Digits only'),
    newPassword: z.string().min(8, 'Password must be at least 8 characters'),
    confirmPassword: z.string(),
  })
  .refine((d) => d.newPassword === d.confirmPassword, {
    message: 'Passwords do not match',
    path: ['confirmPassword'],
  });

type FormData = z.infer<typeof schema>;

export function ResetPasswordPage(): JSX.Element {
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const phoneE164 = params.get('phone') ?? '';
  const [serverError, setServerError] = useState<string | null>(null);

  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<FormData>({ resolver: zodResolver(schema) });

  const onSubmit = async ({ otp, newPassword }: FormData) => {
    setServerError(null);
    try {
      await authApi.resetPassword({ phoneE164, otp, newPassword });
      navigate('/login?reset=1');
    } catch (err: unknown) {
      if (axios.isAxiosError(err)) {
        setServerError(
          (err.response?.data as { message?: string })?.message ??
            'Reset failed. The code may have expired.',
        );
      } else {
        setServerError('Reset failed. Please try again.');
      }
    }
  };

  return (
    <div className={styles.page}>
      <div className={styles.card}>
        <div className={styles.brand}>
          <span className={styles.brandMark}>SL</span>
        </div>
        <h1 className={styles.title}>Reset Password</h1>
        <p className={styles.subtitle}>Enter the code you received and your new password</p>

        {serverError && (
          <div className={`${styles.alert} ${styles.alertError}`} role="alert">
            {serverError}
          </div>
        )}

        <form onSubmit={handleSubmit(onSubmit)} noValidate>
          <div className={styles.field}>
            <label className={styles.label} htmlFor="otp">
              Reset Code
            </label>
            <input
              id="otp"
              className={`${styles.input} ${styles.otpInput}${errors.otp ? ` ${styles.inputError}` : ''}`}
              type="text"
              inputMode="numeric"
              maxLength={6}
              autoComplete="one-time-code"
              placeholder="000000"
              {...register('otp')}
            />
            {errors.otp && (
              <p className={styles.fieldError} role="alert">
                {errors.otp.message}
              </p>
            )}
          </div>

          <hr className={styles.divider} />

          <div className={styles.field}>
            <label className={styles.label} htmlFor="newPassword">
              New Password
            </label>
            <input
              id="newPassword"
              className={`${styles.input}${errors.newPassword ? ` ${styles.inputError}` : ''}`}
              type="password"
              autoComplete="new-password"
              placeholder="Minimum 8 characters"
              {...register('newPassword')}
            />
            {errors.newPassword && (
              <p className={styles.fieldError} role="alert">
                {errors.newPassword.message}
              </p>
            )}
          </div>

          <div className={styles.field}>
            <label className={styles.label} htmlFor="confirmPassword">
              Confirm Password
            </label>
            <input
              id="confirmPassword"
              className={`${styles.input}${errors.confirmPassword ? ` ${styles.inputError}` : ''}`}
              type="password"
              autoComplete="new-password"
              placeholder="Repeat new password"
              {...register('confirmPassword')}
            />
            {errors.confirmPassword && (
              <p className={styles.fieldError} role="alert">
                {errors.confirmPassword.message}
              </p>
            )}
          </div>

          <button type="submit" className={styles.submitBtn} disabled={isSubmitting}>
            {isSubmitting ? 'Resetting…' : 'Reset Password'}
          </button>
        </form>

        <div className={styles.footer}>
          <Link to="/login" className={styles.link}>
            Back to Login
          </Link>
        </div>
      </div>
    </div>
  );
}

export default ResetPasswordPage;
